public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (String str : strings) {
        if (str == null || str.isEmpty()) {
            continue;
        }

        for (int i = 0; i < str.length(); i++) {
            for (int j = i; j < str.length(); j++) {
                String subStr = str.substring(i, j + 1);
                String inverseSubStr = new StringBuilder(subStr).reverse().toString();

                if (anyStringContainsSubstr(strings, subStr) || anyStringContainsSubstr(strings, inverseSubStr)) {
                    maxLength = Math.max(maxLength, subStr.length());
                }
            }
        }
    }

    return maxLength;
}

private boolean anyStringContainsSubstr(List<String> strings, String substr) {
    for (String str : strings) {
        if (str.contains(substr)) {
            return true;
        }
    }
    return false;
}

