public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    int depositCount = 0;

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@') {
                depositCount++;
                dfs(grid, r, c);
            }
        }
    }

    return depositCount;
}

private static void dfs(char[][] grid, int r, int c) {
    if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] == '*') {
        return;
    }

    grid[r][c] = '*';

    dfs(grid, r - 1, c); // up
    dfs(grid, r + 1, c); // down
    dfs(grid, r, c - 1); // left
    dfs(grid, r, c + 1); // right
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int depositCount = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                depositCount++;
                dfs(grid, visited, i, j, rows, cols);
            }
        }
    }

    return depositCount;
}

private static void dfs(char[][] grid, boolean[][] visited, int i, int j, int rows, int cols) {
    if (i < 0 || i >= rows || j < 0 || j >= cols || grid[i][j] != '@' || visited[i][j]) {
        return;
    }

    visited[i][j] = true;

    // Explore all 4 possible directions
    dfs(grid, visited, i - 1, j, rows, cols);
    dfs(grid, visited, i + 1, j, rows, cols);
    dfs(grid, visited, i, j - 1, rows, cols);
    dfs(grid, visited, i, j + 1, rows, cols);
}

