public static int countDoubles(int[] numbers) {
    Set<Integer> doubles = new HashSet<>();
    Set<Integer> seen = new HashSet<>();

    for (int num : numbers) {
        if (seen.contains(2 * num)) {
            doubles.add(num);
        }
        if (num % 2 == 0 && seen.contains(num / 2)) {
            doubles.add(num);
        }
        seen.add(num);
    }

    return doubles.size();
}

