    for (int[] path : paths) {
        int x1 = path[0];
        int y1 = path[1];
        int x2 = path[2];
        int y2 = path[3];
        maze[x1][y1] = true;
        maze[x2][y2] = true;
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    if (!maze[startX][startY] || !maze[endX][endY]) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean[][] canReach = new boolean[n][n];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            canReach[i][j] = false;
        }
    }

    canReach[startX][startY] = true;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (maze[i][j] && canReach[i][j]) {
                if (i > 0 && maze[i - 1][j] && !visited[i - 1][j]) {
                    canReach[i - 1][j] = true;
                }
                if (i < n - 1 && maze[i + 1][j] && !visited[i + 1][j]) {
                    canReach[i + 1][j] = true;
                }
                if (j > 0 && maze[i][j - 1] && !visited[i][j - 1]) {
                    canReach[i][j - 1] = true;
                }
                if (j < n - 1 && maze[i][j + 1] && !visited[i][j + 1]) {
                    canReach[i][j + 1] = true;
                }
                visited[i][j] = true;
            }
        }
    }

    return canReach[endX][endY] ? "can be travelled" : "cannot be travelled";
}

