public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    boolean[] visited = new boolean[n * n];
    int startIndex = getIntersectionIndex(start, n);
    int endIndex = getIntersectionIndex(end, n);

    if (startIndex == -1 || endIndex == -1) {
        return "cannot be travelled";
    }

    return hasPath(paths, visited, startIndex, endIndex) ? "can be travelled" : "cannot be travelled";
}

private static int getIntersectionIndex(int[] coordinates, int n) {
    int x = coordinates[0];
    int y = coordinates[1];
    if (x >= 0 && x < n && y >= 0 && y < n) {
        return x * n + y;
    }
    return -1;
}

private static boolean hasPath(int[][] paths, boolean[] visited, int current, int end) {
    if (current == end) {
        return true;
    }
    visited[current] = true;

    for (int[] path : paths) {
        if ((path[0] == current && path[1] != end && !visited[path[1]]) || (path[1] == current && path[0] != end && !visited[path[0]])) {
            if (hasPath(paths, visited, path[0] == current ? path[1] : path[0], end)) {
                return true;
            }
        }
    }

    return false;
}

