public static String convertDatesToWeekdays(String date) {
    try {
        String[] parts = date.split(" ");
        String month = parts[0];
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        String[] months = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
        String monthStr = months[month - 1];

        String weekday = getWeekday(day, month, year);
        return monthStr + " " + day + ", " + year + " is a " + weekday;
    } catch (Exception e) {
        return "Invalid date format";
    }
}

private static String getWeekday(int day, int month, int year) {
    Calendar calendar = Calendar.getInstance();
    calendar.set(year, month - 1, day);
    int dayOfWeek = calendar.get(Calendar.DAY_OF_WEEK);
    String[] days = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    return days[dayOfWeek - 1];
}

