public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            if (hasSum(nums, i, sum * i / n)) {
                return true;
            }
        }
    }

    return false;
}

private boolean hasSum(int[] nums, int targetSize, int targetSum) {
    int n = nums.length;
    boolean[][] dp = new boolean[targetSize + 1][targetSum + 1];

    for (int i = 0; i <= n; i++) {
        dp[i][0] = true;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= targetSum; j++) {
            if (j < nums[i - 1]) {
                dp[i][j] = dp[i - 1][j];
            } else {
                dp[i][j] = dp[i - 1][j] || dp[i - 1][j - nums[i - 1]];
            }
        }
    }

    return dp[n][targetSum];
}

