            boolean[] dp = new boolean[sum + 1];
            dp[0] = true;

            for (int num : nums) {
                for (int j = sum; j >= num; j--) {
                    dp[j] = dp[j] || dp[j - num];
                    set.add(j * 1.0 / i);
                }
            }

            if (set.contains((sum - sum * i) * 1.0 / (n - i))) return true;
        }
    }

    return false;
}

