        for (int num : nums) {
            Set<Integer> news = new HashSet<>();
            for (int j : s) {
                int newSum = j + num;
                if (newSum == target) {
                    return true;
                }
                news.add(newSum);
            }
            s.addAll(news);
        }
        if (s.contains(target)) {
            return true;
        }
    }
    return false;
}

