public int minOperations(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    int target = n;
    int sum = 0;

    for (int i = 0; i < n; i++) {
        sum += (2 * i) + 1;
    }

    int average = sum / n;
    int operations = 0;

    for (int i = 0; i < n / 2; i++) {
        operations += average - ((2 * i) + 1);
    }

    return operations;
}

