public int minOperations(int n) {
    // The array arr has a length of n, and arr[i] = (2 * i) + 1 for 0 <= i < n.
    // The goal is to make all elements in arr equal.

    // The array arr forms an arithmetic sequence with the first term 1 and common difference 2.
    // The middle element of the array will be the target value to which all elements need to be equal.
    // For an array of odd length, the middle element is (2 * (n / 2)) + 1.
    // For an array of even length, the target value is the average of the two middle elements,
    // which is (2 * ((n / 2) - 1) + 3 + (2 * (n / 2) + 1)) / 2 = (2 * n + 2) / 2 = n + 1.

    int targetValue = (n % 2 == 0) ? n + 1 : (2 * (n / 2)) + 1;
    int operations = 0;

    // Calculate the total number of operations required.
    // For the first half of the array, each element needs to be decreased to the target value.
    for (int i = 0; i < n / 2; i++) {
        operations += targetValue - ((2 * i) + 1);
    }

    return operations;
}

