public int findMinFibonacciNumbers(int k) {
    if (k <= 1) {
        return k;
    }

    int a = 1, b = 1;
    List<Integer> fibs = new ArrayList<>();
    fibs.add(a);
    fibs.add(b);

    while (b < k) {
        int next = a + b;
        a = b;
        b = next;
        fibs.add(next);
    }

    int count = 0;
    while (k > 0) {
        int largestFib = fibs.stream().filter(f -> f <= k).max(Integer::compare).get();
        k -= largestFib;
        count++;
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Generate Fibonacci numbers up to k
    ArrayList<Integer> fibonacciNumbers = new ArrayList<>();
    int a = 1, b = 1;
    fibonacciNumbers.add(a);
    while (b <= k) {
        int temp = b;
        b = a + b;
        a = temp;
        fibonacciNumbers.add(a);
    }

    // Initialize the count of Fibonacci numbers needed
    int count = 0;

    // Use the largest Fibonacci numbers first to minimize the count
    while (k > 0) {
        int maxFib = fibonacciNumbers.get(fibonacciNumbers.size() - 1);
        if (maxFib <= k) {
            k -= maxFib;
            count++;
        } else {
            fibonacciNumbers.remove(fibonacciNumbers.size() - 1);
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    // Step 1: Generate a list of Fibonacci numbers less than or equal to k
    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    while (a <= k) {
        fibs.add(a);
        int next = a + b;
        a = b;
        b = next;
    }

    // Step 2: Count the minimum number of Fibonacci numbers whose sum is equal to k
    int count = 0;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        if (k >= fibs.get(i)) {
            k -= fibs.get(i);
            count++;
        }
    }

    return count;
}

