public String getSmallestString(int n, int k) {
    // Initialize a StringBuilder to build the result string
    StringBuilder sb = new StringBuilder();

    // Fill the first n-1 characters with 'a'
    for (int i = 0; i < n - 1; i++) {
        sb.append('a');
        k -= 1; // Subtract the value of 'a' (1) from k
    }

    // Determine the value for the last character
    int lastCharValue = k;
    if (lastCharValue > 26) {
        lastCharValue = 26;
    }
    sb.append((char) ('a' + lastCharValue - 1));

    return sb.toString();
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a');
    k -= n;

    for (int i = n - 1; i >= 0; i--) {
        if (k == 0) {
            break;
        }

        int add = Math.min(25, k);
        result[i] = (char) (result[i] + add);
        k -= add;
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a'); // Initialize the array with 'a'
    k -= n; // Subtract n because each 'a' contributes 1 to the value

    for (int i = n - 1; i >= 0 && k > 0; i--) {
        int add = Math.min(25, k); // We can add at most 25 to reach 'z'
        result[i] = (char) ('a' + add);
        k -= add;
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a');
    k -= n;

    for (int i = n - 1; i >= 0 && k > 0; i--) {
        int toAdd = Math.min(25, k);
        result[i] += toAdd;
        k -= toAdd;
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0 || k <= 0 || k > 26 * n) {
        throw new IllegalArgumentException("Invalid input values");
    }

    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
        k -= 1;
    }

    int index = n - 1;
    while (k > 0) {
        int add = Math.min(k, 25);
        result[index] += add;
        k -= add;
        index--;
    }

    return new String(result);
}

