        for (int i = 1; i <= 9; i++) {
            dfs(low, high, result, i);
        }
        result.sort(Integer::compareTo);
        return result;
    }

private static void dfs(int low, int high, List<Integer> result, int current) {
        if (current < low) {
            return;
        }
        if (current > high) {
            return;
        }
        result.add(current);
        int lastDigit = current % 10;
        if (lastDigit > 0) {
            dfs(low, high, result, current * 10 + lastDigit - 1);
        }
        if (lastDigit < 9) {
            dfs(low, high, result, current * 10 + lastDigit + 1);
        }
    }

