private static void findSteppingNumbersHelper(List<Integer> result, int number, int low, int high) {
        if (number > high) {
            return;
        }
        int lastDigit = number % 10;
        if (lastDigit + 1 <= 9) {
            int nextNumber = number * 10 + (lastDigit + 1);
            if (nextNumber >= low && nextNumber <= high) {
                result.add(nextNumber);
            }
            findSteppingNumbersHelper(result, nextNumber, low, high);
        }
        if (lastDigit - 1 >= 0) {
            int nextNumber = number * 10 + (lastDigit - 1);
            if (nextNumber >= low && nextNumber <= high) {
                result.add(nextNumber);
            }
            findSteppingNumbersHelper(result, nextNumber, low, high);
        }
    }

