public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    int[][] dp = new int[n][n];
    for (int[] row : dp) {
        Arrays.fill(row, -1);
    }

    return backtrack(A, 0, new HashMap<>(), dp);
}

private static int backtrack(int[] A, int start, Map<Integer, Integer> frequency, int[][] dp) {
    int n = A.length;
    if (start == n - 1) {
        return 1;
    }

    if (dp[start][frequencyHash(frequency)] != -1) {
        return dp[start][frequencyHash(frequency)];
    }

    int result = 0;
    for (int i = start + 1; i < n; i++) {
        if (isPerfectSquare(A[start] + A[i])) {
            int key = A[i];
            frequency.put(key, frequency.getOrDefault(key, 0) + 1);

            result += backtrack(A, i, frequency, dp);

            frequency.put(key, frequency.get(key) - 1);
            if (frequency.get(key) == 0) {
                frequency.remove(key);
            }
        }
    }

    dp[start][frequencyHash(frequency)] = result;
    return result;
}

private static boolean isPerfectSquare(int num) {
    if (num < 0) {
        return false;
    }
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

private static int frequencyHash(Map<Integer, Integer> frequency) {
    int hash = 0;
    for (Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
        hash = hash * 31 + entry.getKey() * 31 + entry.getValue();
    }
    return hash;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length <= 1) {
        return 0;
    }

    int count = 0;
    boolean[] used = new boolean[A.length];
    backtrack(A, used, 0, count);
    return count;
}

private static void backtrack(int[] A, boolean[] used, int start, int[] count) {
    if (start == A.length - 1) {
        count[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i] || (start > 0 && !isPerfectSquare(A[i] + A[start - 1]))) {
            continue;
        }

        used[i] = true;
        backtrack(A, used, start + 1, count);
        used[i] = false;
    }
}

private static boolean isPerfectSquare(int num) {
    if (num < 0) {
        return false;
    }

    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    int[] sqrtSum = new int[n - 1];
    for (int i = 0; i < n - 1; i++) {
        sqrtSum[i] = (int) Math.sqrt(A[i] + A[i + 1]);
    }

    HashMap<Integer, List<Integer>> map = new HashMap<>();
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                map.computeIfAbsent(i, k -> new ArrayList<>()).add(j);
                map.computeIfAbsent(j, k -> new ArrayList<>()).add(i);
            }
        }
    }

    int[] dp = new int[n];
    Arrays.fill(dp, -1);

    return permute(A, map, 0, dp);
}

private static int permute(int[] A, HashMap<Integer, List<Integer>> map, int index, int[] dp) {
    if (index == A.length - 1) {
        return 1;
    }

    if (dp[index] != -1) {
        return dp[index];
    }

    int count = 0;
    for (int next : map.getOrDefault(index, Collections.emptyList())) {
        count += permute(A, map, next, dp);
    }

    dp[index] = count;
    return count;
}

public static int squarePermutations(int[] A) {
