    }

    int n = A.length;
    int[][] dp = new int[n][1 << n];
    dp[0][1 << 0] = 1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 1 << n; j++) {
            if (dp[i][j] == 0) {
                continue;
            }
            for (int k = 0; k < n; k++) {
                if ((j & (1 << k)) != 0) {
                    continue;
                }
                int sum = A[k] + A[i];
                double sqrt = Math.sqrt(sum);
                if (sqrt == (int) sqrt) {
                    dp[k][j | (1 << k)] += dp[i][j];
                }
            }
        }
    }

    int result = 0;
    for (int j = 0; j < 1 << n; j++) {
        result += dp[n - 1][j];
    }

    return result;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length < 2) {
        return 0;
    }

    int n = A.length;
    int[][] dp = new int[n][1 << n];
    for (int i = 0; i < n; i++) {
        dp[i][1 << i] = 1;
    }

    for (int mask = 1; mask < 1 << n; mask++) {
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) > 0) {
                for (int j = 0; j < n; j++) {
                    if (j != i && (mask & (1 << j)) > 0 && isPerfectSquare(A[i] + A[j])) {
                        dp[i][mask] += dp[j][mask ^ (1 << i)];
                    }
                }
            }
        }
    }

    int result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[i][(1 << n) - 1];
    }

    return result;
}

private static boolean isPerfectSquare(int num) {
    if (num < 0) {
        return false;
    }
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

