public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    boolean up = true;

    int row = 0, col = 0;
    for (int i = 0; i < result.length; i++) {
        result[i] = mat[row][col];

        if (up) {
            if (col == cols - 1) {
                row++;
                up = false;
            } else if (row == 0) {
                col++;
                up = false;
            } else {
                row--;
                col++;
            }
        } else {
            if (row == rows - 1) {
                col++;
                up = true;
            } else if (col == 0) {
                row++;
                up = true;
            } else {
                row++;
                col--;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Going up
            int r = Math.min(d, rows - 1);
            int c = d - r;
            while (r >= 0 && c < cols) {
                result[index++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // Going down
            int c = Math.min(d, cols - 1);
            int r = d - c;
            while (c >= 0 && r < rows) {
                result[index++] = mat[r][c];
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
