    int index = 0;

    for (int d = 0; d < m + n - 1; d++) {
        if (d % 2 == 0) {
            // Traverse up
            int row = Math.min(d, m - 1);
            int col = d - row;
            while (row >= 0 && col < n) {
                result[index++] = mat[row--][col++];
            }
        } else {
            // Traverse down
            int col = Math.min(d, n - 1);
            int row = d - col;
            while (row < m && col >= 0) {
                result[index++] = mat[row++][col--];
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
