        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int sum = 0; sum < rows + cols - 1; sum++) {
        if (sum % 2 == 0) {
            // Traverse from top to bottom
            for (int i = Math.min(sum, rows - 1); i >= Math.max(sum - cols + 1, 0); i--) {
                result[index++] = mat[i][sum - i];
            }
        } else {
            // Traverse from bottom to top
            for (int i = Math.max(sum - cols + 1, 0); i <= Math.min(sum, rows - 1); i++) {
                result[index++] = mat[i][sum - i];
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    boolean up = true;
    int row = 0, col = 0, idx = 0;

    while (row >= 0 && row < m && col >= 0 && col < n) {
        result[idx++] = mat[row][col];
        int new_row = row - (up ? 1 : 0) + (up ? 0 : 1);
        int new_col = col - (up ? 0 : 1) + (up ? 1 : 0);

        if (new_row >= 0 && new_row < m && new_col >= 0 && new_col < n) {
            row = new_row;
            col = new_col;
        } else {
            if (up) {
                if (col == n - 1) {
                    row++;
                } else {
                    col++;
                }
            } else {
                if (row == m - 1) {
                    col++;
                } else {
                    row++;
                }
            }
            up = !up;
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;

    // Find the first digit that is smaller than the digit next to it from the right
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1 (not possible to find a greater number)
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i) which is greater than digits[i]
    int j;
    for (j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the (i)th position
    Arrays.sort(digits, i + 1, length);

    // Convert the digits back to a number
    int result = Integer.parseInt(new String(digits));

    // Check if the result is greater than the original number
    if (result > n) {
        return result;
    } else {
        return -1;
    }
}

