public static List<String> centerSymmetricNumbers(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    List<String> result = new ArrayList<>();
    HashSet<Character> set = new HashSet<>();
    set.add('0');
    set.add('1');
    set.add('6');
    set.add('8');
    set.add('9');
    helper(result, new char[n], set, 0, n - 1);
    return result;
}

private static void helper(List<String> result, char[] current, HashSet<Character> set, int left, int right) {
    if (left > right) {
        result.add(String.copyValueOf(current));
        return;
    }
    if (left == right) {
        for (char c : set) {
            if (c != '0' || left != 0) {
                current[left] = c;
                result.add(String.copyValueOf(current));
            }
        }
        return;
    }
    for (char c : set) {
        if (c == '6') {
            current[left] = '6';
            current[right] = '9';
        } else if (c == '9') {
            current[left] = '9';
            current[right] = '6';
        } else {
            current[left] = c;
            current[right] = c;
        }
        helper(result, current, set, left + 1, right - 1);
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return Collections.emptyList();
    }

    Map<Character, Character> pairs = new HashMap<>();
    pairs.put('0', '0');
    pairs.put('1', '1');
    pairs.put('6', '9');
    pairs.put('8', '8');
    pairs.put('9', '6');

    List<String> result = new ArrayList<>();
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
    } else {
        generateRecursively(pairs, n, new char[n], 0, n - 1, result);
    }

    return result;
}

private static void generateRecursively(Map<Character, Character> pairs, int n, char[] current, int left, int right, List<String> result) {
    if (left > right) {
        result.add(new String(current));
        return;
    }

    if (left == right) {
        for (char c : pairs.keySet()) {
            if (c == '0' && left != 0) continue; // Avoid leading zero
            current[left] = c;
            result.add(new String(current));
        }
    } else {
        for (Map.Entry<Character, Character> entry : pairs.entrySet()) {
            char leftChar = entry.getKey();
            char rightChar = entry.getValue();
            current[left] = leftChar;
            current[right] = rightChar;
            generateRecursively(pairs, n, current, left + 1, right - 1, result);
        }
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }
    if (n == 1) {
        return Arrays.asList("0", "1", "8");
    }
    List<String> result = new ArrayList<>();
    dfs(result, "", n, n);
    return result;
}

private static void dfs(List<String> result, String path, int n, int len) {
    if (len == 0) {
        if (path.length() > 0 || path.equals("0")) {
            result.add(path);
        }
        return;
    }
    if (len == 1) {
        for (char c : new char[]{'0', '1', '8'}) {
            result.add(path + c + path);
        }
        return;
    }
    for (char c : new char[]{'1', '6', '8', '9'}) {
        dfs(result, c + path + c, n, len - 2);
    }
}

public static List<String> centerSymmetricNumbers(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input length n must be non-negative.");
        }

        List<String> result = new ArrayList<>();
        char[] choices = {'0', '1', '8'};
        if (n == 1) {
            for (char choice : choices) {
                if (choice != '0') {
                    result.add(String.valueOf(choice));
                }
            }
            return result;
        }

        generate(n, 0, new char[n], result, choices);
        return result;
    }

private static void generate(int n, int index, char[] current, List<String> result, char[] choices) {
        if (index == n / 2) {
            addSymmetricNumber(n, current, result, choices);
            return;
        }
        for (char choice : choices) {
            current[index] = choice;
            if (index != n - 1 - index) {
                current[n - 1 - index] = getSymmetricChar(choice);
            }
            if (index == 0 && choice == '0') {
                continue; // Skip leading zeros
            }
            generate(n, index + 1, current, result, choices);
        }
    }

private static void addSymmetricNumber(int n, char[] current, List<String> result, char[] choices) {
        if (n == 1) {
            for (char choice : choices) {
                if (choice == '0') {
                    continue; // Skip leading zeros
                }
                result.add(String.valueOf(choice));
            }
        } else {
            result.add(new String(current));
        }
    }

private static char getSymmetricChar(char choice) {
        if (choice == '1') {
            return '1';
        } else if (choice == '8') {
            return '8';
        } else if (choice == '6') {
            return '9';
        } else if (choice == '9') {
            return '6';
        }
        throw new IllegalArgumentException("Invalid character for center symmetric number: " + choice);
    }

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    helper(result, new char[n], 0, n - 1);
    return result;
}

private static void helper(List<String> result, char[] chars, int left, int right) {
    if (left > right) {
        result.add(new String(chars));
        return;
    }
    if (left == right) {
        chars[left] = '0';
        result.add(new String(chars));
        chars[left] = '1';
        result.add(new String(chars));
        chars[left] = '8';
        return;
    }
    if (left != 0) {
        chars[left] = '0';
        chars[right] = '0';
        helper(result, chars, left + 1, right - 1);
    }
    chars[left] = '1';
    chars[right] = '1';
    helper(result, chars, left + 1, right - 1);
    chars[left] = '6';
    chars[right] = '9';
    helper(result, chars, left + 1, right - 1);
    chars[left] = '8';
    chars[right] = '8';
    helper(result, chars, left + 1, right - 1);
    chars[left] = '9';
    chars[right] = '6';
    helper(result, chars, left + 1, right - 1);
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];

    // Calculate the area of the triangle formed by the points using the determinant method
    int area = p1[0] * (p2[1] - p3[1]) + p2[0] * (p3[1] - p1[1]) + p3[0] * (p1[1] - p2[1]);

    // If the area is zero, the points are collinear and do not form a boomerang
    return area != 0;
}

